// ---------------- Parameters ----------------
plate_length   = 100;   // base plate length (X)
plate_width    = 30;    // base plate width (Y)
plate_thick    = 6;     // base plate thickness (Z), z = 0..6

rail_base_w    = 12;    // dovetail width where it meets the plate (z = 6)
rail_top_w     = 18;    // dovetail width at its top face (z = 12)
rail_top_z     = 12;    // top face height of the rail
rail_length    = plate_length; // rail runs the full plate length

overlap        = 0.01;  // small overlap to fuse rail into plate

$fn = 64;

// ---------------- Modules ----------------
module base_plate() {
    translate([-plate_length/2, -plate_width/2, 0])
        cube([plate_length, plate_width, plate_thick]);
}

// Trapezoid cross-section in the YZ plane, extruded along X
module dovetail_rail() {
    // rotate([90,0,90]) maps 2D x -> Y, 2D y -> Z, extrusion -> X
    rotate([90, 0, 90])
        linear_extrude(height = rail_length, center = true)
            polygon(points = [
                [-rail_base_w/2, plate_thick - overlap],
                [ rail_base_w/2, plate_thick - overlap],
                [ rail_top_w/2,  rail_top_z],
                [-rail_top_w/2,  rail_top_z]
            ]);
}

// ---------------- Assembly ----------------
union() {
    base_plate();
    dovetail_rail();
}

