block_y      = 30;    // block size in Y (mm)
block_z      = 12;    // block height in Z (mm)

hole_d       = 4.5;   // through-hole diameter (mm)

hex_flats    = 7.2;   // hex pocket size across flats (mm)
hex_depth    = 3.4;   // hex pocket depth from bottom face (mm)

eps          = 0.5;   // overshoot for clean boolean cuts (mm)

// Derived values
hex_circ_r   = hex_flats / sqrt(3);   // circumradius = flats / (2*cos(30))

// ---------------- Model ----------------
difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Vertical through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = block_z + 2 * eps, $fn = 96);

    // Hex nut pocket from the bottom face.
    // A 6-sided cylinder has vertices on the X axis,
    // so two of its flats are parallel to the X axis.
    translate([0, 0, -eps])
        cylinder(r = hex_circ_r, h = hex_depth + eps, $fn = 6);
}

