// Split collet - round tube with axial slots from the top end
$fn = 96;

// --- Dimensions (mm) ---
tube_od      = 16;    // tube outer diameter
tube_id      = 12;    // bore diameter
tube_h       = 25;    // tube height (z = 0 to 25)
slot_count   = 6;     // number of axial slots
slot_w       = 1.5;   // slot width
slot_bottom  = 15;    // slots run from top down to this z
first_angle  = 0;     // first slot centred on +X axis
eps          = 0.5;   // overcut for clean boolean faces

difference() {
    // Tube body
    cylinder(d = tube_od, h = tube_h);

    // Bore (through)
    translate([0, 0, -eps])
        cylinder(d = tube_id, h = tube_h + 2 * eps);

    // Axial slots through the wall, from z = slot_bottom to above the top
    for (i = [0 : slot_count - 1])
        rotate([0, 0, first_angle + i * 360 / slot_count])
            translate([tube_id / 2 - eps, -slot_w / 2, slot_bottom])
                cube([(tube_od - tube_id) / 2 + 2 * eps,
                      slot_w,
                      tube_h - slot_bottom + eps]);
}

