half_ext = half_top * (groove_depth + overcut) / groove_depth;

// ---------- Model ----------
difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_h]);

    // V-grooves, centred along X, running the full width in Y
    for (i = [0 : groove_count - 1]) {
        x = (i - (groove_count - 1) / 2) * groove_pitch;
        translate([x, 0, 0])
            rotate([90, 0, 0])   // polygon X-Y plane -> X-Z plane, extrude along Y
                linear_extrude(height = block_wid + 2*overcut, center = true)
                    polygon([
                        [0,          block_h - groove_depth],  // V tip
                        [ half_ext,  block_h + overcut],       // top right (above surface)
                        [-half_ext,  block_h + overcut]        // top left (above surface)
                    ]);
    }
}

