block_y      = 26;     // block width along Y (mm)
block_h      = 28;     // block height along Z (mm)

pocket_w     = 12.8;   // square pocket side (mm)
pocket_depth = 23;     // pocket depth from top face (mm)
pocket_pitch = 19.8;   // centre-to-centre spacing along X (mm)
pocket_count = 5;      // number of cuvette pockets

eps          = 0.5;    // cutter overshoot past top face (mm)

$fn = 64;

// Floor thickness under pockets (= 28 - 23 = 5 mm)
floor_t = block_h - pocket_depth;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_h]);

    // Row of square pockets, centred on the block
    for (i = [0 : pocket_count - 1]) {
        px = (i - (pocket_count - 1) / 2) * pocket_pitch;
        translate([px - pocket_w / 2, -pocket_w / 2, floor_t])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
    }
}

