                cylinder(d = pocket_d, h = pocket_depth + eps, $fn = fn_curve);

    // Central through-hole for motor shaft
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = disc_h + 2 * eps, $fn = fn_curve);
}

