pocket_depth = 12;    // depth of each hex pocket from the top face (mm)
pocket_pitch = 14;    // centre-to-centre spacing of pockets along X (mm)
pocket_af    = [2.4, 2.9, 3.4, 4.4, 5.4, 6.4]; // across-flats sizes, -X to +X (mm)
pocket_count = len(pocket_af);                  // number of pockets

overcut      = 0.5;   // extra length of the cutters past the top face (mm)

// Circumradius of a regular hexagon from its across-flats size
function hex_r(af) = af / (2 * cos(30));

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_hgt]);

    // Hexagonal pockets along y = 0, centred on the block
    for (i = [0 : pocket_count - 1]) {
        x = (i - (pocket_count - 1) / 2) * pocket_pitch;
        // $fn = 6 places vertices on the X axis, so two flats are parallel to X
        translate([x, 0, block_hgt - pocket_depth])
            cylinder(r = hex_r(pocket_af[i]),
                     h = pocket_depth + overcut,
                     $fn = 6);
    }
}

