wall    = 2.5;

$fn = 64;

ib = max(1.6, spout_d - 2 * wall);   // keep the spout bore open even if the wall is thick

translate([0, 0, spout_l])          // rest the spout tip on the bed (z = 0)
difference() {
    union() {
        cylinder(h = cone_h, d1 = spout_d, d2 = top);                 // cone: spout end up to mouth
        translate([0, 0, -spout_l]) cylinder(h = spout_l + 0.01, d = spout_d);   // spout below
    }
    translate([0, 0, -spout_l - 1])
        cylinder(h = spout_l + 1 + 0.01, d = ib);                     // bore through the spout
    cylinder(h = cone_h + 1, d1 = ib, d2 = top - 2 * wall);           // inner cone, open mouth
}

// Flanged idler pulley - a smooth grooved wheel with side flanges and an axial bore, for a
// round or flat belt. NOVEL general mechanical part.
//

od     = 36.8;
width  = 15.8;
flange = 5.4;
bore   = 11.6;

$fn = 96;

flange_t = 2;

difference() {
    union() {
        cylinder(h = width, d = od);
        cylinder(h = flange_t, d = od + 2 * flange);
        translate([0, 0, width - flange_t]) cylinder(h = flange_t, d = od + 2 * flange);
    }
    rotate_extrude() translate([od / 2, width / 2, 0]) circle(d = width * 0.5);   // belt groove
    translate([0, 0, -1]) cylinder(h = width + 2, d = bore);
}

// Component tray - a rectangular plate with a regular grid of round pockets, for sorting small
// parts, fasteners or samples. NOVEL general part (a generic pocket grid, not any one labware item).
//

cols   = 4;
rows   = 4;
pocket = 11.7;
depth  = 6.8;
pitch  = 29.7;
wall   = 1.8;

$fn = 48;

p  = max(pitch, pocket + 2 * wall);          // keep a wall between neighbouring pockets
Lx = (cols - 1) * p + pocket + 2 * wall;
Ly = (rows - 1) * p + pocket + 2 * wall;
H  = depth + wall;

difference() {
    cube([Lx, Ly, H]);
    for (i = [0 : cols - 1], j = [0 : rows - 1])
        translate([wall + pocket / 2 + i * p, wall + pocket / 2 + j * p, wall])
            cylinder(h = depth + 1, d = pocket);   // blind pocket, open at the top face
}

// Funnel - a conical mouth narrowing into a straight spout, hollow with a constant wall. NOVEL
// general part (a generic funnel, not any one labware item).
//

top     = 75.3;
spout_d = 18.7;
cone_h  = 43.8;
spout_l = 11.1;
wall    = 2.6;

$fn = 64;

ib = max(1.6, spout_d - 2 * wall);   // keep the spout bore open even if the wall is thick

translate([0, 0, spout_l])          // rest the spout tip on the bed (z = 0)
difference() {
    union() {
        cylinder(h = cone_h, d1 = spout_d, d2 = top);                 // cone: spout end up to mouth
        translate([0, 0, -spout_l]) cylinder(h = spout_l + 0.01, d = spout_d);   // spout below
    }
    translate([0, 0, -spout_l - 1])
        cylinder(h = spout_l + 1 + 0.01, d = ib);                     // bore through the spout
    cylinder(h = cone_h + 1, d1 = ib, d2 = top - 2 * wall);           // inner cone, open mouth
}

// Pillow block - a bench block that supports a horizontal shaft through a bore, bolted down
// at each end. NOVEL general mechanical mount.
//

bore = 9.6;
bw   = 57.9;
bl   = 41.4;
bolt = 7.2;

$fn = 72;

H = bore + 16;                 // height so the bore has wall above and below

difference() {
    translate([-bw / 2, -bl / 2, 0]) cube([bw, bl, H]);
    translate([0, -bl / 2 - 1, H / 2]) rotate([-90, 0, 0]) cylinder(h = bl + 2, d = bore);   // horizontal bore
    for (x = [-bw * 0.38, bw * 0.38])
        translate([x, 0, -1]) cylinder(h = H + 2, d = bolt);                                 // bolt holes
}

// J-hook wall hook - a backplate with mounting holes and a projecting hook with an upturned
// tip. NOVEL general part.
//

plate_w = 21;
reach   = 50.9;
lip     = 21.9;
screw   = 3.3;

$fn = 48;

plate_h = 50;
t       = 5;
arm     = 8;

difference() {
    union() {
        cube([plate_w, t, plate_h]);                                              // backplate
        translate([plate_w / 2 - arm / 2, 0, plate_h * 0.25]) cube([arm, reach, arm]);           // arm
        translate([plate_w / 2 - arm / 2, reach - arm, plate_h * 0.25]) cube([arm, arm, lip]);   // upturned tip
    }
    for (z = [plate_h * 0.25, plate_h * 0.75])
        translate([plate_w / 2, -1, z]) rotate([-90, 0, 0]) cylinder(h = t + 2, d = screw);
}

// Channel / T-slot nut - a rectangular block with a bolt bore, for aluminium extrusion or a
// slotted channel. NOVEL general part.
//

w    = 15;
l    = 22.2;
h    = 3.9;
bore = 8;

$fn = 48;

difference() {
    translate([-w / 2, -l / 2, 0]) cube([w, l, h]);
    translate([0, 0, -1]) cylinder(h = h + 2, d = bore);
}

// T pipe connector - a tee joining three tube ends, hollow through. NOVEL general part.
//

bore   = 7.1;
wall   = 3.7;
run    = 74.1;
branch = 19.7;

$fn = 64;

od = bore + 2 * wall;

difference() {
    union() {
        translate([-run / 2, 0, 0]) rotate([0, 90, 0]) cylinder(h = run, d = od);   // run along X
        rotate([-90, 0, 0]) cylinder(h = branch, d = od);                            // branch along +Y
    }
    translate([-run / 2 - 1, 0, 0]) rotate([0, 90, 0]) cylinder(h = run + 2, d = bore);
    rotate([-90, 0, 0]) translate([0, 0, -1]) cylinder(h = branch + 2, d = bore);
}

// Open-top storage bin / parts tray - a rectangular box open at the top, for small parts
// or bench organisation. NOVEL general part.
//

inner_l = 182;
inner_w = 140.4;
height  = 80.8;
wall    = 2.5;

difference() {
    cube([inner_l + 2 * wall, inner_w + 2 * wall, height]);
    translate([wall, wall, wall]) cube([inner_l, inner_w, height]);     // hollow, open top
}

// Right-angle corner bracket - two perpendicular arms with a mounting hole in each, to
// join two surfaces at 90 degrees. NOVEL general structural part.
//

arm   = 60.8;
width = 15.9;
t     = 6.2;
hole  = 6;

$fn = 48;

difference() {
    union() {
        cube([arm, width, t]);      // horizontal arm (along X)
        cube([t, width, arm]);      // vertical arm (along Z)
    }
    translate([arm * 0.72, width / 2, -1]) cylinder(h = t + 2, d = hole);                 // horizontal arm hole
    translate([-1, width / 2, arm * 0.72]) rotate([0, 90, 0]) cylinder(h = t + 2, d = hole);  // vertical arm hole
}

// Round motor mount plate - a disk with a center bore and a bolt circle, to mount a round
// motor or bearing. NOVEL general part.
//

plate_d     = 97.4;
bore        = 8.1;
bolt_circle = 86.7;
holes       = 7;
screw       = 4.8;
t           = 4;

$fn = 72;

difference() {
    cylinder(h = t, d = plate_d);
    translate([0, 0, -1]) cylinder(h = t + 2, d = bore);
    for (i = [0 : holes - 1])
        rotate([0, 0, i * 360 / holes]) translate([bolt_circle / 2, 0, -1]) cylinder(h = t + 2, d = screw);
}
